        carrier.set(() -> {
            throw ApiException.unavailable("CARRIER_UNAVAILABLE");
        });
        r = call("POST", "/checkout/summary",
                purchase("[{\"sku\":\"TEN-001\",\"quantity\":1}]", "ECONOMY", null, "PIX", 1, "BRONZE", "NORTH"));
